-- Custom quest steps imported from Unity (QuestObjectiveType.Custom, run by a scene reactor).
-- The editor shows them locked; only task-set task minigames are editable (payload.tasks).
insert into public.step_type_definitions (id, unity_objective, description, fields, metadata) values ('custom', 'Custom', 'A Unity-built step run by a scene reactor (task set, cutscene, encounter...); only task minigames are editable', '[{"description":"Unity objective targetId (the reactor''s handler id)","name":"handler_id","readonly":true,"required":true,"type":"string"},{"description":"Index in QuestDefinitionSO.objectives; the scene reactor binds to it","name":"unity_objective_index","readonly":true,"required":true,"type":"integer"},{"name":"count","readonly":true,"required":false,"type":"integer"},{"description":"task_set | cutscene | escort | monster_encounter | choice_rounds | wave_defense | museum","name":"reactor","readonly":true,"required":true,"type":"string"},{"description":"task_set only: one entry per spot {index, name, mode: scene|minigame|none, minigame_id, instance_key, ...}","name":"tasks","required":false,"type":"json"}]'::jsonb, '{"locked":true}'::jsonb) on conflict (id) do update set unity_objective = excluded.unity_objective, description = excluded.description, fields = excluded.fields, metadata = excluded.metadata, updated_at = now();
